function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPxeIssues(
  query: Record<string, string | number | boolean>,
): Promise<PxeIssueListItem[]> {
  const res = await apiClient.get<BffResponse<PxeIssueListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPxeIssue(sttRec: string): Promise<PxeIssue> {
  const res = await apiClient.get<BffResponse<PxeIssue>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createPxeIssue(body: PxeIssueWrite): Promise<PxeIssue> {
  const res = await apiClient.post<BffResponse<PxeIssue>>(BASE, body);
  return unwrap(res);
}

export async function updatePxeIssue(sttRec: string, body: PxeIssueWrite): Promise<PxeIssue> {
  const res = await apiClient.put<BffResponse<PxeIssue>>(`${BASE}/${encodeURIComponent(sttRec)}`, body);
  return unwrap(res);
}
